package com.example.rokidkeyboardbridge;
public final class NaturalPosePolicyTest {
 static int n;static void ok(boolean v,String message){n++;if(!v)throw new AssertionError(message);}
 static NaturalPosePolicy free(long now){NaturalPosePolicy p=new NaturalPosePolicy();p.user("隣に座って",now);return p;}
 public static void main(String[] args){long t=10000;for(String q:new String[]{"隣に座って","となりに座って","ロキ、そばに座ってください","隣に来て座って","となりにきてすわって","こっちに来て座って","隣に座ってくれる？"}){ok(ComfortPoseIntent.action(q)==0,"adjacent alias "+q);EmbodiedScenePolicy body=new EmbodiedScenePolicy();body.user(q,t);ok(body.restMotion(t)==8&&body.posture()==1,"actual hug seat "+q);body.answer(ComfortPoseIntent.reply(0),FullBodyPoseCatalog.Kind.NEUTRAL,t+50);ok(body.restMotion(t+50)==8,"spoken reply retains seated pose");}
 for(String q:new String[]{"隣に座ってとは？","彼女が隣に座っている","隣に座ってと言った","隣に座ってほしくない","隣に座っている画像を検索して"})ok(ComfortPoseIntent.action(q)<0,"ordinary text "+q);
 for(String q:new String[]{"自然にいろんなポーズをとって","自然にいろんなポーズもとって","ポーズはおまかせ","ロキ、ポーズをおまかせにして"})ok(NaturalPosePolicy.control(q)==1&&EmbodiedScenePolicy.visualCommand(q),"local auto enable");for(String q:new String[]{"自然にポーズをとってと言った","彼女のポーズはおまかせ？","ポーズを固定してほしくない"})ok(NaturalPosePolicy.control(q)<0,"control exclusion");
 NaturalPosePolicy p=free(t);ok(p.select(8,t+21999,0,false,false,true)==8,"entry hold");ok(p.select(8,t+22000,0,false,false,true)==11,"same seated posture variation");ok(p.active()&&p.age(t+22500)==500,"bounded presentation clock");ok(p.select(8,t+22000+NaturalPosePolicy.DURATION,0,false,false,true)==8,"return to requested base pose");ok(!p.active(),"variation completes");ok(p.select(8,t+50000,0,false,false,true)==8,"no frequent repetition");
 p=free(t);p.user("膝を抱えて座って",t+1);ok(p.select(8,t+100000,0,false,false,true)==8&&!p.active(),"explicit pose never replaced");p=free(t);p.user("ポーズを固定して",t+1);ok(!p.enabled()&&p.select(8,t+100000,0,false,false,true)==8,"fixed mode stops posture changes");p.user("ポーズはおまかせ",t+2);ok(p.enabled()&&p.select(8,t+22002,0,false,false,true)==11,"auto resumes explicitly");
 for(int blocked=0;blocked<5;blocked++){p=free(t);int selected=p.select(8,t+22001,blocked==0?1:blocked==1?2:0,blocked==2,blocked==3,blocked!=4);ok(selected==8&&!p.active(),"listening/speaking/navigation/manual face/body-off priority");ok(p.select(8,t+22002,0,false,false,true)==8,"defer after interruption");}
 p=free(t);p.answer(FullBodyPoseCatalog.Kind.SAD,t+100);ok(p.select(8,t+22001,0,false,false,true)==8,"no playful change in sad exchange");p=free(t);p.select(8,t+22001,0,false,false,true);p.mode(1,t+22002);ok(!p.active(),"new question cancels variation");p=free(t);p.select(8,t+22001,0,false,false,true);ok(p.select(8,t-1,0,false,false,true)==8&&!p.active(),"clock rewind safe");
 ok(NaturalPosePolicy.alternative(5)<0&&NaturalPosePolicy.alternative(7)<0,"knees never auto lowered");ok(NaturalPosePolicy.alternative(0)==10&&NaturalPosePolicy.alternative(9)==10,"lying stays lying");ok(NaturalPosePolicy.alternative(8)==11&&NaturalPosePolicy.alternative(11)==8,"seated stays seated");ok(NaturalPosePolicy.alpha(0)==0&&NaturalPosePolicy.alpha(6400)==0&&NaturalPosePolicy.alpha(650)==1,"finite fade");for(int i=0;i<6400;i+=100)ok(NaturalPosePolicy.alpha(i)>=0&&NaturalPosePolicy.alpha(i)<=1,"blend bounds");
 int old=CharacterMotionTuning.bodyLevel;CharacterMotionTuning.bodyLevel=2;ok(NaturalPosePolicy.everyday(100000,false,true)==6,"ordinary open hand standing");ok(NaturalPosePolicy.everyday(280000,true,true)==25,"ordinary notebook seated");ok(NaturalPosePolicy.everyday(104600,false,true)<0,"finite everyday clip");ok(NaturalPosePolicy.everyday(100000,false,false)<0,"auto preference respected");CharacterMotionTuning.bodyLevel=0;ok(NaturalPosePolicy.everyday(100000,false,true)<0,"body off respected");CharacterMotionTuning.bodyLevel=old;System.out.println("PASS "+n+" adjacent/natural-pose/priority/cadence checks");}
}
